function Cart() {
  const cart = JSON.parse(localStorage.getItem('cart')) || [];

  return (
    <div className="container">
      <h1 className="title">Your Cart</h1>

      {cart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        cart.map((item, index) => (
          <div className="card" key={index}>
            <h3>{item.title}</h3>

            <p>{item.description}</p>

            <p>₹ {item.price}</p>
          </div>
        ))
      )}
    </div>
  );
}

export default Cart;
